```python
import stripe
import time

stripe.api_key = 'your_stripe_api_key'

class StripeExtractor:
    def __init__(self, last_run_timestamp):
        self.last_run_timestamp = last_run_timestamp

    def extract_data(self):
        self.extract_subscriptions()

    def extract_subscriptions(self):
        try:
            for subscription in stripe.Subscription.list(limit=100, created={"gte": self.last_run_timestamp}).auto_paging_iter():
                self.handle_subscription(subscription)
                time.sleep(0.2)  # Adjust for rate limiting
        except stripe.error.RateLimitError as e:
            self.handle_rate_limit(e)

    def handle_subscription(self, subscription):
        # Flatten subscription items into separate rows
