    def handle_rate_limit(self, error):
        retries = 0
        while retries < 5:
            time.sleep(2 ** retries)  # Exponential backoff
            retries += 1
        if retries == 5:
            raise error

extractor = StripeExtractor(last_run_timestamp=1625097600)  # Example timestamp
